const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {createHandler}=require('../api/model-calibrations.js');
function fixture(){let contents=null,etag=0;const store={get:async()=>contents?{statusCode:200,blob:{etag:String(etag)},stream:new Response(contents).body}:null,put:async(p,body,opts)=>{if(contents&&opts.ifMatch!==String(etag))throw Object.assign(Error(),{name:'BlobPreconditionFailedError'});contents=body;etag++;}};const handler=createHandler(store);async function call(body,auth='test-key',origin='https://ranch.test'){let code,output;await handler({method:body?'POST':'GET',headers:{host:'ranch.test',origin,authorization:'Bearer '+auth},body},{setHeader(){},set statusCode(v){code=v},end(v){output=JSON.parse(v)}});return {status:code,data:output};}return {call,store};}
function browser(){const values=new Map();values.set('ranch-view-pair-v1','test-key');return {getItem:k=>values.get(k)??null,setItem:(k,v)=>values.set(k,v),removeItem:k=>values.delete(k)};}
let counter=0;async function client(){return import('../model-calibration.js?test='+counter++);}
process.env.RANCH_VIEW_WRITE_KEY='test-key';
test('shared API authenticates writes, validates IDs, retains other models and rejects stale saves',async()=>{const f=fixture();assert.equal((await f.call({id:'horse-idle',metresPerUnit:1,approved:false},'wrong')).status,401);assert.equal((await f.call({id:'horse-idle',metresPerUnit:1,approved:false},'test-key','https://elsewhere.test')).status,403);assert.equal((await f.call({id:'../bad',metresPerUnit:1,approved:false})).status,400);const a=await f.call({id:'horse-idle',metresPerUnit:.9,approved:true});assert.equal(a.status,200);assert(a.data.record.approvedAt);assert.equal((await f.call({id:'cow-idle',metresPerUnit:1.1,approved:false})).status,200);assert.equal((await f.call({id:'horse-idle',metresPerUnit:2,approved:false})).status,409);const cleared=await f.call({id:'horse-idle',metresPerUnit:null,approved:false,expectedRevision:a.data.record.revision});assert.equal(cleared.status,200);assert.equal((await f.call()).data.models['horse-idle'].metresPerUnit,null);assert.equal((await f.call()).data.models['cow-idle'].metresPerUnit,1.1);});
test('save survives a fresh browser, migration respects shared values, reset survives stale legacy caches, failure stays unsaved',async()=>{const f=fixture();global.window={dispatchEvent(){}};global.localStorage=browser();global.fetch=async(url,opts={})=>{const r=await f.call(opts.body?JSON.parse(opts.body):null);return new Response(JSON.stringify(r.data),{status:r.status})};const a=await client();await a.refreshCalibrations();await a.saveCalibration('family-home-complete',2.1,{approved:true});assert.equal(a.calibratedScale('family-home-complete'),2.1);global.localStorage=browser();const b=await client();await b.refreshCalibrations();assert.equal(b.calibratedScale('family-home-complete'),2.1);assert(b.readCalibrations()['family-home-complete'].approvedAt);await b.clearCalibration('family-home-complete');assert.equal(b.calibratedScale('family-home-complete'),2);global.localStorage=browser();localStorage.setItem(b.CALIBRATION_KEY,JSON.stringify({version:1,models:{'family-home-complete':{metresPerUnit:9},'horse-idle':{metresPerUnit:.95,approvedAt:'old'}}}));const c=await client();await c.refreshCalibrations();assert.equal(c.calibratedScale('family-home-complete'),2);assert.equal(c.calibratedScale('horse-idle'),.95);assert(localStorage.getItem('ranch-model-calibration-legacy-backup'));global.fetch=async()=>{throw Error('offline')};await assert.rejects(c.saveCalibration('horse-idle',3),/offline/);assert.equal(c.calibratedScale('horse-idle'),.95);for(const bad of [0,-1,NaN,Infinity])assert.throws(()=>c.saveCalibration('horse-idle',bad));});
test('all catalog variants have consistent family defaults without manufactured approvals',async()=>{global.localStorage=browser();const m=await client(),catalog=JSON.parse(fs.readFileSync(path.join(__dirname,'../simulation-assets/catalog.json'))),families=new Map();for(const r of catalog){const scale=m.projectScale(r.id);assert(Number.isFinite(scale)&&scale>0,r.id);if(families.has(r.subject))assert.equal(scale,families.get(r.subject));families.set(r.subject,scale);}assert.equal(catalog.length,98);assert.equal(m.modelDimensions('daddy-idle',{x:.838,y:1.934,z:.582}).h,1.934);assert.deepEqual(m.readCalibrations(),{});assert.equal(m.projectScale('unknown'),null);});

test('an empty authoritative registry clears a stale synced cache before offline fallback',async()=>{global.window={dispatchEvent(){}};global.localStorage=browser();localStorage.setItem('ranch-model-calibration-v1',JSON.stringify({version:1,remoteSynced:true,models:{'horse-idle':{metresPerUnit:9}}}));global.fetch=async()=>new Response(JSON.stringify({version:1,models:{}}));const m=await client();await m.refreshCalibrations();assert.equal(m.calibratedScale('horse-idle'),1);global.fetch=async()=>{throw Error('offline')};await m.refreshCalibrations();assert.equal(m.calibratedScale('horse-idle'),1);});
